CREATE TABLE mineral_occurrences (id INTEGER PRIMARY KEY AUTOINCREMENT,company_id BIGINT NOT NULL REFERENCES companies(id) ON DELETE CASCADE,monitoring_area_id BIGINT NOT NULL,name TEXT NOT NULL,source TEXT NOT NULL CHECK(source IN ('SGB')),external_id TEXT NOT NULL,substance TEXT NOT NULL,occurrence_type TEXT,economic_status TEXT,importance TEXT,description TEXT,source_url TEXT NOT NULL,source_updated_at TEXT,geometry TEXT NOT NULL,metadata_json TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(company_id,monitoring_area_id,source,external_id),FOREIGN KEY(monitoring_area_id,company_id) REFERENCES monitoring_areas(id,company_id) ON DELETE CASCADE);
CREATE INDEX mineral_occurrences_area_idx ON mineral_occurrences(company_id,monitoring_area_id,substance);
